const N=x=>Number(x)||0, F=(x,d=0)=>x==null||!Number.isFinite(+x)?'—':new Intl.NumberFormat('en-US',{minimumFractionDigits:d,maximumFractionDigits:d}).format(+x), pct=x=>x==null?'—':`${F(x,1)}%`;
const arr=x=>Array.isArray(x)?x:[]; const uniq=a=>[...new Set(a.filter(Boolean))];
