const STATES={raw:null,loading:false,error:'',view:'rd',year:'2026',region:'all',category:'all',tier:'all',supplier:'all',detail:null,createEvent:false,localEvents:[]};
try{const x=JSON.parse(sessionStorage.getItem('pharma.v2919.quality.local')||'[]');if(Array.isArray(x))STATES.localEvents=x.filter(r=>String(r.event_id||'').startsWith('LOCAL-DEMO-')).slice(0,100)}catch{}
try{const x=JSON.parse(sessionStorage.getItem('pharma.sourcing.shared.selection')||'{}');if(x.region)STATES.region=x.region;if(x.category)STATES.category=x.category}catch{}
