document.addEventListener('change',e=>{const evt=e.target.closest('.spf-page [data-spf-event-status]');if(evt){const row=STATES.localEvents.find(x=>x.event_id===evt.dataset.spfEventStatus);if(row){row.progress=evt.value;try{sessionStorage.setItem('pharma.v2919.quality.local',JSON.stringify(STATES.localEvents.slice(0,100)))}catch{}if(location.hash==='#ss-performance')window.render?.()}return}const el=e.target.closest('.spf-page [data-spf-filter]');if(!el)return;STATES[el.dataset.spfFilter]=el.value;try{sessionStorage.setItem('pharma.sourcing.shared.selection',JSON.stringify({region:STATES.region,category:STATES.category}))}catch{}if(location.hash==='#ss-performance')window.render?.()});
